node -e 'const fs=require("fs");const fail=(m)=>{console.error(m+" (LIVE-727)");process.exit(1)}
const norm=(s)=>s.replace(/\/\*[\s\S]*?\*\//g," ").replace(/^\s*\/\/.*$/gm," ")
const rd=(f)=>{try{return norm(fs.readFileSync(f,"utf8"))}catch(e){return null}}
const em=rd("lib/spaces/email.ts"),dr=rd("lib/spaces/drip-runner.ts"),ed=rd("lib/spaces/email-drafts.ts")
if(em===null||dr===null||ed===null)process.exit(79)
const fn=(s,start)=>{const i=s.indexOf(start);if(i<0)return null;const j=s.indexOf("\n}",i);return j<0?null:s.slice(i,j)}
const m=em.match(/export function spaceEmailHold\([\s\S]*?\n\}/)
if(!m)fail("nothing decides whether a Space may send email from its status, so a suspended Space keeps sending")
const ts=require("typescript");const hold=new Function(ts.transpileModule(m[0].replace("export ",""),{compilerOptions:{target:99}}).outputText+";return spaceEmailHold")()
if(hold("active")!==null)fail("an active Space is refused email")
for(const st of ["suspended","archived",null,undefined,"Active"])if(!hold(st))fail("a Space whose status is "+String(st)+" may still send email")
const dc=fn(em,"async function deliverSpaceCampaign(")
if(!dc)fail("the Space campaign delivery core is gone")
const g=dc.search(/const (\w+) = spaceEmailHold\(space\.status\)\s*if \(\1\) \{\s*(log\.warn\([^)]*\)\s*)?return fail\(SPACE_NOT_ACTIVE_EMAIL_ERROR\)/)
if(g<0||g>dc.indexOf("enqueue("))fail("the delivery core queues a campaign, drip or broadcast without refusing a suspended Space first")
if(!/outreachSendId: sendId,\s*spaceId,/.test(dc))fail("a queued Space campaign job does not carry its spaceId, so the drain cannot re-check the Space")
const dh=fn(em,"export const runSpaceCampaignEmail")
if(!dh)fail("the Space campaign drain handler is gone")
const pr=dh.indexOf("sendRawEmail(")
const dg=dh.search(/spaceEmailHold\([\s\S]*?\)\s*if \(hold\) \{[\s\S]*?cancelQueuedSend\([\s\S]*?return\s*\}/)
if(pr<0||dg<0||dg>pr)fail("a campaign job queued before its Space was suspended still reaches the provider at drain time")
const cq=fn(em,"async function cancelQueuedSend(")
if(!cq||!/status: \x27failed\x27, error: note/.test(cq))fail("a job the drain refuses is not marked on its ledger row, so the cancel is silent")
const rb=fn(dr,"export async function runDueSpaceDrips(")
if(!rb)fail("the drip runner is gone")
const hb=rb.match(/if \(isError\(res\) && res\.error === SPACE_NOT_ACTIVE_EMAIL_ERROR\) \{([\s\S]*?)continue/)
if(!hb||!/await hold\(db, row\.id, row\.current_step,/.test(hb[1])||/markStatus\(/.test(hb[1]))fail("a suspended Space stops its drip enrollments instead of holding them at their step")
if(rb.indexOf(hb[0])>rb.search(/if \(isError\(res\)\) \{/))fail("the drip runner stops an enrollment before it can see the suspended-Space refusal")
const hf=fn(dr,"async function hold(")
if(!hf||!/update\(\{ status: \x27enrolled\x27, current_step: step, next_run_at: nextRunAt \}\)/.test(hf))fail("a held drip enrollment is not released back to enrolled at the same step")
const cv=fn(ed,"export async function sendSpaceEmailDraftAsConversations(")
if(!cv)fail("the Space member composer send is gone")
const cg=cv.search(/if \(spaceEmailHold\(space\.status\)\) return fail\(SPACE_NOT_ACTIVE_EMAIL_ERROR\)/)
if(cg<0||cg>cv.indexOf("startConversationMessage("))fail("the Space member composer mails from a suspended Space")
console.log("ok")'
